export const SIZE_CONTRACT_VERSION="size_contract_v1_2";export const DEFAULT_SIZE_TOLERANCE=Object.freeze({relative:.05,floorMm:0});export const SIZE_TOLERANCE_BY_SOURCE=Object.freeze({verified:Object.freeze({relative:.05,floorMm:0}),manual:Object.freeze({relative:.05,floorMm:0})});export const SIZE_VERIFIED_METHODS=Object.freeze(["caliper","marker_photo","erp"]);export const SIZE_VERIFIED_SOURCES=Object.freeze(["caliper","marker_photo","erp","camera_measured"]);export const SIZE_SQUARE_CLASS_MAX_DIFF=.05;export const SIZE_MAX_MM=5e3;const SIZE_ROUND_DIGITS=6;function round(value,digits=SIZE_ROUND_DIGITS){if(!Number.isFinite(value))return null;const factor=10**digits;return Math.round(value*factor)/factor}function toFiniteNumber(value){if(typeof value==="number")return Number.isFinite(value)?value:null;if(typeof value==="string"){const normalized=value.trim().replace(",",".");if(!normalized)return null;const parsed=Number(normalized);return Number.isFinite(parsed)?parsed:null}return null}function sanitizeTolerance(tolerance){const relative=toFiniteNumber(tolerance?.relative);const floorMm=toFiniteNumber(tolerance?.floorMm);return{relative:relative!=null&&relative>=0?relative:DEFAULT_SIZE_TOLERANCE.relative,floorMm:floorMm!=null&&floorMm>=0?floorMm:DEFAULT_SIZE_TOLERANCE.floorMm}}export function normalizeSizePair(length,width,{maxMm:maxMm=SIZE_MAX_MM}={}){const l=toFiniteNumber(length);const w=toFiniteNumber(width);if(l==null&&w==null)return null;const cap=toFiniteNumber(maxMm)??SIZE_MAX_MM;if(l==null){if(w<=0||w>cap)return null;return{length_mm:w,width_mm:null}}if(l<=0||l>cap)return null;if(w==null)return{length_mm:l,width_mm:null};if(w<=0||w>cap)return null;return l>=w?{length_mm:l,width_mm:w}:{length_mm:w,width_mm:l}}export function shapeClass(lengthMm,widthMm){const pair=normalizeSizePair(lengthMm,widthMm);if(!pair||pair.width_mm==null)return null;const diff=Math.abs(pair.length_mm-pair.width_mm)/pair.length_mm;return diff<=SIZE_SQUARE_CLASS_MAX_DIFF?"square":"rect"}export function toleranceForEdge(refMm,tolerance=DEFAULT_SIZE_TOLERANCE){const ref=toFiniteNumber(refMm);if(ref==null||ref<=0)return null;const tol=sanitizeTolerance(tolerance);return Math.max(tol.relative*ref,tol.floorMm)}export function isVerifiedMeasurement(side){if(!side||typeof side!=="object")return false;const method=String(side.method||"").trim().toLowerCase();const source=String(side.source||"").trim().toLowerCase();return SIZE_VERIFIED_METHODS.includes(method)||SIZE_VERIFIED_SOURCES.includes(source)}export function resolveSizeTolerance(querySide,candidateSide,explicit){const relative=toFiniteNumber(explicit?.relative);const floorMm=toFiniteNumber(explicit?.floorMm);if(relative!=null||floorMm!=null)return sanitizeTolerance(explicit);const verified=isVerifiedMeasurement(querySide)&&isVerifiedMeasurement(candidateSide);const chosen=verified?SIZE_TOLERANCE_BY_SOURCE.verified:SIZE_TOLERANCE_BY_SOURCE.manual;return{relative:chosen.relative,floorMm:chosen.floorMm}}function compareEdges(queryPair,candidatePair,tolerance){const tol=sanitizeTolerance(tolerance);const hasWidth=queryPair.width_mm!=null&&candidatePair.width_mm!=null;const keys=hasWidth?["length_mm","width_mm"]:["length_mm"];const edges=keys.map(key=>{const q=queryPair[key];const c=candidatePair[key];const delta=Math.abs(q-c);const ref=q;const allowed=Math.max(tol.relative*ref,tol.floorMm);return{key:key,delta:round(delta),allowed:round(allowed),ok:delta<=allowed+1e-9}});const longEdge=edges[0];const dMax=longEdge.delta/queryPair.length_mm;return{ok:longEdge.ok,partial:!hasWidth,d_max:round(dMax),edges:edges}}export function sizeDistance(queryPair,candidatePair){const q=normalizeSizePair(queryPair?.length_mm??queryPair?.lengthMm,queryPair?.width_mm??queryPair?.widthMm);const c=normalizeSizePair(candidatePair?.length_mm??candidatePair?.lengthMm,candidatePair?.width_mm??candidatePair?.widthMm);if(!q||!c)return null;return compareEdges(q,c,DEFAULT_SIZE_TOLERANCE).d_max}export function evaluateSizeMatch(queryPair,candidatePair,tolerance){const q=normalizeSizePair(queryPair?.length_mm??queryPair?.lengthMm,queryPair?.width_mm??queryPair?.widthMm);const c=normalizeSizePair(candidatePair?.length_mm??candidatePair?.lengthMm,candidatePair?.width_mm??candidatePair?.widthMm);if(!q||!c){return{status:"unknown",permutation:null,d_max:null,edges:[],tolerance:null}}const tol=resolveSizeTolerance(queryPair,candidatePair,tolerance);const identity=compareEdges(q,c,tol);const chosen=identity;const permutation="identity";return{status:chosen.ok?chosen.partial?"match_partial":"match":"mismatch",permutation:permutation,d_max:chosen.d_max,edges:chosen.edges,tolerance:tol}}export function normalizeQuerySize(input){if(!input||typeof input!=="object")return null;const pair=normalizeSizePair(input.length_mm??input.lengthMm,input.width_mm??input.widthMm);if(!pair)return null;const source=typeof input.source==="string"&&/^[a-z0-9_]{1,32}$/.test(input.source)?input.source:"unknown";const confidence=typeof input.confidence==="number"&&Number.isFinite(input.confidence)&&input.confidence>=0&&input.confidence<=1?input.confidence:null;return{length_mm:pair.length_mm,width_mm:pair.width_mm,shape_class:shapeClass(pair.length_mm,pair.width_mm),source:source,confidence:confidence}}export function formatSizePair(pair){const normalized=normalizeSizePair(pair?.length_mm??pair?.lengthMm,pair?.width_mm??pair?.widthMm);if(!normalized)return"";const fmt=value=>{const rounded=Math.round(value*10)/10;return String(rounded)};if(normalized.width_mm==null)return`${fmt(normalized.length_mm)} mm`;return`${fmt(normalized.length_mm)} × ${fmt(normalized.width_mm)} mm`}